from datetime import date; from decimal import Decimal; from src.extraction.orm.layer2 import AtomicPosition; from src.extraction.orm.layer3 import CostBasisMethod, ManagedPosition, PositionStatus; from src.ledger import Account, AccountType; from src.pricing.orm.market_data import FxRate; _ACQ_DATE = date(2025, 1, 15); _HKD_TO_SGD = Decimal('0.17'); _NATIVE_COST = Decimal('10000.00'); _EXPECTED_BASE_COST = Decimal('1700.00')
async def _seed_position(db, test_user, *, with_fx_rate: bool) -> ManagedPosition: account = Account(user_id=test_user.id, name='HK Broker', type=AccountType.ASSET, currency='HKD'); db.add(account); await db.flush(); position = ManagedPosition(user_id=test_user.id, account_id=account.id, asset_identifier='0700.HK', quantity=Decimal('100.0'), cost_basis=_NATIVE_COST, acquisition_date=_ACQ_DATE, status=PositionStatus.ACTIVE, currency='HKD', cost_basis_method=CostBasisMethod.FIFO, position_metadata={'broker': 'HK Broker'}); snapshot = AtomicPosition(user_id=test_user.id, snapshot_date=_ACQ_DATE, asset_identifier='0700.HK', broker='HK Broker', quantity=Decimal('100.0'), market_value=_NATIVE_COST, currency='HKD', dedup_hash='hk_0700_native_snapshot', source_documents={}); db.add_all([position, snapshot]); db.add(FxRate(base_currency='HKD', quote_currency='SGD', rate=_HKD_TO_SGD, rate_date=_ACQ_DATE, source='test')) if with_fx_rate else None; await db.commit(); await db.refresh(position); return position
def _find_holding(holdings: list[dict], position_id: str) -> dict: match = next((h for h in holdings if h['id'] == position_id), None); assert match is not None, f'holding {position_id} not found in {holdings}'; return match
async def test_ac1_reporting_cost_basis_reconciles_on_base(client, db, test_user): position = await _seed_position(db, test_user, with_fx_rate=True); positions_resp = await client.get('/assets/positions'); assert positions_resp.status_code == 200; item = next((i for i in positions_resp.json()['items'] if i['id'] == str(position.id))); holdings_resp = await client.get('/portfolio/holdings'); assert holdings_resp.status_code == 200; holding = _find_holding(holdings_resp.json()['items'], str(position.id)); assert item['reporting_currency'] == 'SGD'; assert Decimal(str(item['reporting_cost_basis'])) == _EXPECTED_BASE_COST; assert holding['currency'] == 'SGD'; assert Decimal(str(item['reporting_cost_basis'])) == Decimal(str(holding['cost_basis']))
async def test_ac2_native_values_reconcile(client, db, test_user): position = await _seed_position(db, test_user, with_fx_rate=True); positions_resp = await client.get('/assets/positions'); assert positions_resp.status_code == 200; item = next((i for i in positions_resp.json()['items'] if i['id'] == str(position.id))); holdings_resp = await client.get('/portfolio/holdings'); assert holdings_resp.status_code == 200; holding = _find_holding(holdings_resp.json()['items'], str(position.id)); assert item['currency'] == 'HKD'; assert Decimal(str(item['cost_basis'])) == _NATIVE_COST; assert holding['native_currency'] == 'HKD'; assert Decimal(str(holding['native_cost_basis'])) == _NATIVE_COST; assert item['currency'] == holding['native_currency']; assert Decimal(str(item['cost_basis'])) == Decimal(str(holding['native_cost_basis']))
async def test_ac3_missing_fx_rate_does_not_500(client, db, test_user): position = await _seed_position(db, test_user, with_fx_rate=False); positions_resp = await client.get('/assets/positions'); assert positions_resp.status_code == 200; item = next((i for i in positions_resp.json()['items'] if i['id'] == str(position.id))); assert item['currency'] == 'HKD'; assert Decimal(str(item['cost_basis'])) == _NATIVE_COST; assert item['reporting_cost_basis'] is None; assert item['reporting_currency'] is None; single_resp = await client.get(f'/assets/positions/{position.id}'); assert single_resp.status_code == 200; single = single_resp.json(); assert single['reporting_cost_basis'] is None; assert single['reporting_currency'] is None
async def test_native_and_reporting_currency_fields_are_identically_named_across_endpoints(client, db, test_user): position = await _seed_position(db, test_user, with_fx_rate=True); positions_resp = await client.get('/assets/positions'); assert positions_resp.status_code == 200; item = next((i for i in positions_resp.json()['items'] if i['id'] == str(position.id))); holdings_resp = await client.get('/portfolio/holdings'); assert holdings_resp.status_code == 200; holding = _find_holding(holdings_resp.json()['items'], str(position.id)); assert item['native_currency'] == holding['native_currency'] == 'HKD'; assert item['reporting_currency'] == holding['reporting_currency'] == 'SGD'; assert Decimal(str(item['native_cost_basis'])) == Decimal(str(holding['native_cost_basis'])) == _NATIVE_COST; assert Decimal(str(item['reporting_cost_basis'])) == Decimal(str(holding['reporting_cost_basis'])) == _EXPECTED_BASE_COST; assert item['native_currency'] == item['currency']; assert holding['reporting_currency'] == holding['currency']
